mapper.select:
select edu_course_package.id as id,edu_course.logo as logo, edu_course_package.parent_course_id, edu_course_package.completion_status , edu_course_package.course_id ,edu_course_package.sort , edu_course.course_name,edu_course.sell_type , edu_course.current_price,edu_course_package.teachers,edu_course_package.teacher_ids,edu_course_package.teacher_id from edu_course_package left join edu_course on edu_course_package.course_id = edu_course.id
edu_course.id is not null
and edu_course_package.parent_course_id = #{coursePackage.parentCourseId}
and edu_course.course_name like concat('%',#{coursePackage.courseName},'%')
and edu_course.sell_type = #{coursePackage.sellType}
order by edu_course_package.sort desc

select edu_course_package.id as id, edu_course_package.completion_status as completion_status, edu_course_package.parent_course_id ,edu_course_package.course_id ,edu_course_package.sort ,edu_course.course_name,edu_course.sell_type ,edu_course.current_price ,edu_course.title,edu_course.logo,edu_course_package.teachers,edu_course_package.teacher_ids,edu_course_package.teacher_id from edu_course_package left join edu_course on edu_course_package.course_id = edu_course.id
edu_course.id is not null
and edu_course_package.parent_course_id = #{parentCourseId}
and edu_course.course_name like concat('%',#{courseName},'%')
and edu_course.sell_type = #{sellType}
order by edu_course_package.sort desc
